import{d as g,C as t,o as d,c as h,a3 as e,E as i,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三章","description":"《正易心法》第三章——卦象视人，本无文字：羲皇不立文字，使天下嘿观其象；顺象则吉凶自应，违象则吉凶反。开篇三章至此完成认识论建构。","frontmatter":{"title":"正易心法·第三章","description":"《正易心法》第三章——卦象视人，本无文字：羲皇不立文字，使天下嘿观其象；顺象则吉凶自应，违象则吉凶反。开篇三章至此完成认识论建构。","category":"guide","aliases":["正易心法第三章","卦象视人本无文字","不言之教"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-03.md","filePath":"yijing/zheng-yi-xin-fa/chapter-03.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-03.md"},x=g({...c,setup(u){const s=[{id:"z3-01",label:"一、卦象视人",showLabel:!0,sentences:[["卦象",{text:"视人",glossary:"shiRen"},"，本无文字，使人",{text:"消息",glossary:"xiaoxi"},"，吉凶",{text:"嘿会",glossary:"moHui"},"。"]],note:["卦象是展示给人看的，本来没有文字；它让人体察阴阳消长，默默领会吉凶。（「视」通「示」，是展示、告示之义；「嘿」同「默」。这一句是本章的总纲：卦画本身即为表达，不假文字。）"]},{id:"z3-02",label:"二、嘿观其象",showLabel:!0,sentences:[["羲皇始画八卦，重为六十四，不立文字，使天下之人",{text:"嘿观",glossary:"moGuan"},"其象而已。"]],note:["伏羲最初画八卦，重叠为六十四卦，不立任何文字，只是让天下之人默默观察卦象而已。（静默观象、内心体悟，是伏羲的教法；文字是后来才加上去的一层。）"]},{id:"z3-03",label:"三、如象与违象",showLabel:!0,sentences:[["能",{text:"如象",glossary:"ruXiang"},"焉，则吉凶应；",{text:"违其象",glossary:"weiXiang"},"，则吉凶反。"]],note:["能够顺应卦象之理而行，则吉凶如期应验；违背卦象之理，则吉凶反转。这里的「吉凶应」不是趋吉避凶的算计，而是说：卦象本身就是天道运行的写照，顺之则人与天道合一，自然感应；违之则人与天道割裂，感应失灵。"]},{id:"z3-04",label:"四、不言之教",showLabel:!0,sentences:[["此羲皇氏作",{text:"不言之教",glossary:"buyanZhijiao"},"也。"]],note:["这就是伏羲氏所创的「不言之教」。（这四个字直接来自《老子》「行不言之教」——麻衣把它从老子移给了伏羲：卦象就是道的显现，道不可言，所以卦象本无文字。这一嫁接，正显出陈抟一脉以道解易的底色。）"]},{id:"z3-05",label:"五、郑康成略知此说",showLabel:!0,sentences:[[{text:"郑康成",glossary:"zhengKangcheng"},{text:"略知",glossary:"lvezhi"},"此说。"]],note:["郑康成（郑玄）对此略有所知。这是本章分量最重的一句：看似轻描淡写，实则是「已知门在何处，却仍留在门外」的评语——郑玄重卦气说，知道卦与天道节律相应，但仍以训诂文字的方式治《易》，所以说「略知」。"]}],o=[{id:"shiRen",term:"视人",pinyin:"shì rén",meaning:"示人、给人看。「视」在此通「示」，是展示、告示之义。"},{id:"xiaoxi",term:"消息",pinyin:"xiāo xī",meaning:"阴阳消长。同第一章用法，指体察阴阳进退之理。"},{id:"moHui",term:"嘿会",pinyin:"mò huì",meaning:"嘿同「默」，默默领会。不需文字说明而心中自会。"},{id:"moGuan",term:"嘿观",pinyin:"mò guān",meaning:"默默观察。静默观象、内心体悟，是伏羲的教法。"},{id:"ruXiang",term:"如象",pinyin:"rú xiàng",meaning:"顺应卦象。行为与卦象所示之理相符。"},{id:"weiXiang",term:"违其象",pinyin:"wéi qí xiàng",meaning:"违背卦象。行为与卦象所示之理相悖。"},{id:"buyanZhijiao",term:"不言之教",pinyin:"bù yán zhī jiào",meaning:"《老子》「行不言之教」，指无需语言文字的教化方式。麻衣以此说伏羲画卦。"},{id:"zhengKangcheng",term:"郑康成",pinyin:"zhèng kāng chéng",meaning:"郑玄（127—200），字康成，东汉经学大师，遍注群经。其易学重卦气说，即卦与节气、月令的对应。"},{id:"lvezhi",term:"略知",pinyin:"lüè zhī",meaning:"略微知晓。言下之意：知而未尽，仅得皮毛——摸到了门边，却仍留在文字功夫里。"}];return(b,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=e(`<h1 id="正易心法·第三章" tabindex="-1">正易心法·第三章 <a class="header-anchor" href="#正易心法·第三章" aria-label="Permalink to &quot;正易心法·第三章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>第三章是<strong>前两章的逻辑收束</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一章：要知落处，不盲诵文字</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>第二章：卦画是阴阳运动、血气流行的自然写照</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>第三章：所以羲皇根本就没有文字，文字是后来加上去的</span></span></code></pre></div><p>三章合起来构成一个完整论证——麻衣用开篇三章的篇幅，确立《易》的第一个认识论前提：</p><blockquote><p><strong>《易》的本体是象，不是辞。</strong></p></blockquote><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>本章有两处关键：</p><p><strong>「不言之教」的来处</strong>——这四个字直接来自《老子》：</p><blockquote><p>是以圣人处无为之事，行不言之教，万物作焉而不辞。——《道德经》第二章</p></blockquote><p>麻衣做了一次极精妙的<strong>嫁接</strong>：</p><table tabindex="0"><thead><tr><th>《老子》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>圣人行不言之教</td><td>羲皇作不言之教</td></tr><tr><td>道不可言说</td><td>卦象不需文字</td></tr><tr><td>万物自化</td><td>嘿观自会吉凶</td></tr><tr><td>言则非道</td><td>辞则非象</td></tr></tbody></table><p><strong>卦象就是道的显现；道不可言，所以卦象本无文字。</strong> 这个等式在陈抟体系里至关重要——陈抟本人就是道家传人，他的易学根本上是<strong>以道解易</strong>。</p><p><strong>「郑康成略知此说」</strong>——看似轻描淡写，实则是最高的评价、也是最严的批评：</p><ul><li>郑玄<strong>知道的</strong>：卦象与天道节律有对应（卦气说）；</li><li>郑玄<strong>不知道的</strong>：卦象本无文字，应当「嘿观」而非训诂。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>把<strong>三个历史层次</strong>看清楚：羲皇画卦（无文字）→ 文王系辞（有文字）→ 孔子作传（义理化）；</li><li>记住麻衣的立场：<strong>第一层是本，第二三层是末</strong>；</li><li>再读「郑康成略知此说」——<strong>为什么单点郑玄？</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>视人</strong>：「视」通「示」——卦象是给人看的东西。</li><li><strong>嘿观</strong>：不立文字，静默观象。</li><li><strong>如象 / 违其象</strong>：顺之则吉凶应，违之则吉凶反。</li><li><strong>不言之教</strong>：语出《老子》，麻衣移之于伏羲。</li><li><strong>郑康成略知</strong>：知卦气而不知嘿观，故曰「略知」。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),i(r,{colophon:"本无文字 · 嘿观其象 · 如象违象 · 不言之教",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三章原文",sections:s,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如「嘿」同「默」、「视」通「示」），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"视人",pinyin:["shì","rén"],meaning:"示人、给人看。「视」在此通「示」，是展示、告示之义。"},{term:"嘿观",pinyin:["mò","guān"],meaning:"默默观察。静默观象、内心体悟，是伏羲的教法。"},{term:"如象 / 违其象",pinyin:["rú","xiàng"],meaning:"顺应卦象则吉凶应；违背卦象则吉凶反。卦象即天道之写照，顺之则合一，违之则割裂。"},{term:"不言之教",pinyin:["bù","yán"],meaning:"《老子》「行不言之教」。麻衣移之于伏羲：卦象即道，道不可言，故卦象本无文字。"},{term:"郑康成",pinyin:["zhèng","kāng","chéng"],meaning:"郑玄（127—200），字康成，东汉经学大师。重卦气说——知卦与天道相应，但仍以训诂治《易》，故云「略知」。"}]}),n[3]||(n[3]=e(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>三章合起来的完整论证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦画有落处（第一章）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>落处在自然节律中（第二章）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>所以卦画本身就够了，文字是多余的（第三章）</span></span></code></pre></div><p><strong>这是麻衣在全书开篇用三章篇幅，彻底确立一个认识论前提：《易》的本体是象，不是辞。</strong></p><h3 id="理-「不言之教」从哪来" tabindex="-1">理：「不言之教」从哪来 <a class="header-anchor" href="#理-「不言之教」从哪来" aria-label="Permalink to &quot;理：「不言之教」从哪来&quot;">​</a></h3><p>直接来自《老子》：「是以圣人处无为之事，行不言之教，万物作焉而不辞。」</p><p>麻衣在这里做了一个<strong>极精妙的嫁接</strong>：</p><table tabindex="0"><thead><tr><th>《老子》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>圣人行不言之教</td><td>羲皇作不言之教</td></tr><tr><td>道不可言说</td><td>卦象不需文字</td></tr><tr><td>万物自化</td><td>嘿观自会吉凶</td></tr><tr><td>言则非道</td><td>辞则非象</td></tr></tbody></table><p><strong>把伏羲画卦等同于老子的道</strong>——这个等式在陈抟体系里至关重要，因为陈抟本人就是道家传人，他的易学根本上是以道解易。</p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>先分清<strong>三个历史层次</strong>（无文字 → 有文字 → 义理化）；</li><li>再把「不言之教」的出处找出来（《老子》第二章）；</li><li>带着一个问题往下读：<strong>麻衣自己也在写书，他矛盾吗？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>卦象是展示给人看的，本来没有文字；它让人体察阴阳消长，默默领会吉凶。</p><p>伏羲最初画八卦，重叠为六十四卦，不立任何文字，只是让天下之人默默观察卦象而已。</p><p>能够顺应卦象之理而行，则吉凶如期应验；违背卦象之理，则吉凶反转。</p><p>这就是伏羲氏所创的「不言之教」。郑康成（郑玄）对此略有所知。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三章把开篇两章的论证收了口——<strong>既然卦画有落处、落处在自然节律中，那么文字就是多加的一层；「不言之教」四个字，麻衣是从《老子》借来的。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「视人」</strong>——卦象是「给人看」的，那我看卦时，是先看象，还是先看注？</li><li><strong>「不言之教」的嫁接</strong>——麻衣把老子的「圣人」换成「羲皇」。这一步意味着，<strong>在他眼里《易》与《道德经》是同一件事的两种说法</strong>。这个判断，我认不认？</li><li><strong>「郑康成略知此说」</strong>——为什么单点郑玄？因为他<strong>知卦气而不知嘿观</strong>：摸到了门边，却仍留在训诂里。「略知」二字，既是褒也是贬。</li><li><strong>麻衣自己的悖论</strong>（他埋的钩子）：如果卦象本无文字，那《正易心法》这本书，不也是在用文字解释无文字之象吗？——<strong>这一层他自己很清楚</strong>，后文会说「《易》道不传，乃有周、孔」。这本书是「<strong>以指指月</strong>」的那根手指。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「违其象，则吉凶反」的「反」，是颠倒，还是反弹？</strong> 是吉变凶、凶变吉的<strong>颠倒</strong>，还是天道以更大的力量<strong>纠偏</strong>？——这一问在实占里很实用，先挂在这里。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「不盲诵古人语」</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-02">第二章 · 六画之设</a> — 卦画是自然节律的写照（本章据此推出「文字多余」）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「圣人设卦观象，系辞焉而明吉凶」：麻衣恰恰要说「系辞」是不得已</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 十翼中的文字推演一脉</li></ul>`,23))])}}});export{y as __pageData,x as default};
